import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"常武","description":"","frontmatter":{"title":"常武","date":"2026-11-09T00:00:00.000Z","seq":29,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/常武.md","filePath":"blogs/诗经·大雅/常武.md"}'),p={name:"blogs/诗经·大雅/常武.md"};function r(c,a,l,n,_,i){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="常武" tabindex="-1">常武 <a class="header-anchor" href="#常武" aria-label="Permalink to &quot;常武&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　荡之什</p><div class="poem"><p class="poem-stanza">赫赫明明。王命卿士，南仲大祖，大师皇父。整我六师，以修我戎。既敬既戒，惠此南国。</p><p class="poem-stanza">王谓尹氏，命程伯休父，左右陈行。戒我师旅，率彼淮浦，省此徐土。不留不处，三事就绪。</p><p class="poem-stanza">赫赫业业，有严天子。王舒保作，匪绍匪游。徐方绎骚，震惊徐方。如雷如霆，徐方震惊。</p><p class="poem-stanza">王奋厥武，如震如怒。进厥虎臣，阚如虓虎。铺敦淮濆，仍执丑虏。截彼淮浦，王师之所。</p><p class="poem-stanza">王旅啴啴，如飞如翰。如江如汉，如山之苞。如川之流，绵绵翼翼。不测不克，濯征徐国。</p><p class="poem-stanza">王犹允塞，徐方既来。徐方既同，天子之功。四方既平，徐方来庭。徐方不回，王曰还归。</p></div>',3)])])}const u=e(p,[["render",r]]);export{d as __pageData,u as default};
